DROP TABLE IF EXISTS `inspection`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inspection` (
  `inspection_id` int NOT NULL AUTO_INCREMENT,
  `return_id` int NOT NULL,
  `inspector` varchar(100) NOT NULL,
  `condition_status` enum('GOOD','DAMAGED','DEFECTIVE') NOT NULL,
  `notes` varchar(255) DEFAULT NULL,
  `inspected_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`inspection_id`),
  UNIQUE KEY `return_id` (`return_id`),
  CONSTRAINT `inspection_ibfk_1` FOREIGN KEY (`return_id`) REFERENCES `returnrequest` (`return_id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=543 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

