DROP TABLE IF EXISTS `refund`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `refund` (
  `refund_id` int NOT NULL AUTO_INCREMENT,
  `return_id` int NOT NULL,
  `payment_id` int NOT NULL,
  `amount` decimal(10,2) NOT NULL,
  `refund_status` enum('Pending','Processed','Failed') NOT NULL DEFAULT 'Processed',
  `processed_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`refund_id`),
  KEY `return_id` (`return_id`),
  KEY `payment_id` (`payment_id`),
  KEY `idx_refund_status` (`refund_status`),
  CONSTRAINT `refund_ibfk_1` FOREIGN KEY (`return_id`) REFERENCES `returnrequest` (`return_id`) ON DELETE RESTRICT,
  CONSTRAINT `refund_ibfk_2` FOREIGN KEY (`payment_id`) REFERENCES `payment` (`payment_id`) ON DELETE RESTRICT,
  CONSTRAINT `refund_chk_1` CHECK ((`amount` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=293 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
