CREATE TABLE `returnrequest` (
  `return_id` int NOT NULL AUTO_INCREMENT,
  `order_id` int NOT NULL,
  `customer_id` int NOT NULL,
  `reason` varchar(120) NOT NULL,
  `return_status` enum('Requested','Approved','Received','Inspected','Rejected','Refunded') NOT NULL DEFAULT 'Requested',
  `requested_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `inspected_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`return_id`),
  KEY `idx_return_customer_id` (`customer_id`),
  KEY `idx_return_order_id` (`order_id`),
  KEY `idx_return_status` (`return_status`),
  CONSTRAINT `returnrequest_ibfk_1` FOREIGN KEY (`order_id`) REFERENCES `orders` (`order_id`) ON DELETE RESTRICT,
  CONSTRAINT `returnrequest_ibfk_2` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`customer_id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=1323 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
